pub struct LoadWorkUseCase {
    uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>,
}

impl LoadWorkUseCase {
    pub fn new(uow_factory: Box<dyn LoadWorkUnitOfWorkFactoryTrait>) -> Self {
        LoadWorkUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &LoadWorkDto) -> Result<()> {
        let now = chrono::Utc::now();

        // Stage 1: read + map the file into a neutral graph (no store access yet).
        let shape = skrib::detect_shape(&dto.file_name)
            .with_context(|| format!("inspecting '{}'", dto.file_name))?;
        let loaded = match shape {
            SkribShape::LegacySqlite => {
                let project = legacy::read_project(&dto.file_name)
                    .with_context(|| format!("reading legacy project '{}'", dto.file_name))?;
                legacy_to_loaded(project, now)
            }
            SkribShape::ZipFile | SkribShape::ExplodedFolder => {
                let bundle = skrib::read_bundle(&dto.file_name)
                    .with_context(|| format!("reading project '{}'", dto.file_name))?;
                skrib::bundle_to_loaded(bundle, &dto.file_name)?
            }
        };

        // Stage 2: materialise entities in a single transaction. First close the
        // currently-open work (no-op on a fresh store) — opening a work replaces
        // it. Shared helper, NOT a use-case call (use cases never call each other).
        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        work_io::close_current_work(&*uow)?;

        let mat = materialize(&*uow, &loaded)?;
        create_trunk(&*uow, &loaded, &mat, &dto.file_name, shape, now)?;

        uow.commit()?;
        uow.publish_load_work_event(vec![mat.work_id], None);
        Ok(())
    }
}

struct Materialized {
    work_id: EntityId,
    /// ProgressSnapshot orphans built here (they need `item_map` to remap `book_item_ids`),
    /// wired onto the freshly-created WorkInfo in `create_trunk`.
    progress_snapshot_ids: Vec<EntityId>,
}

/// Materialise the Work subtree (lossless: every scalar field, content row,
/// ordering and M2M link is preserved; file ids are remapped to fresh store ids).
fn materialize(uow: &dyn LoadWorkUnitOfWorkTrait, loaded: &LoadedWork) -> Result<Materialized> {
    let lw = &loaded.work;
    let work = uow.create_orphan_work(&Work {
        created_at: lw.created_at,
        updated_at: lw.updated_at,
        title: lw.title.clone(),
        author_name: lw.author_name.clone(),
        dict_language: lw.dict_language.clone(),
        // Single heal point for every load (legacy + new-format): preserve the
        // source's stable id, or mint a fresh one when it has none.
        unique_id: if lw.unique_id.is_empty() {
            skrib_format::new_unique_id()
        } else {
            lw.unique_id.clone()
        },
        ..Default::default()
    })?;

    // Tags (file id -> new id).
    let mut tag_map: HashMap<u64, EntityId> = HashMap::new();
    let mut tag_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.tags {
        let created = uow.create_orphan_binder_tag(&BinderTag {
            created_at: t.created_at,
            updated_at: t.updated_at,
            name: t.name.clone(),
            color: t.color.clone(),
            details: t.details.clone(),
            discoverable: t.discoverable,
            ..Default::default()
        })?;
        tag_map.insert(t.id, created.id);
        tag_ids.push(created.id);
    }

    // Dictionary words.
    let mut dict_word_ids: Vec<EntityId> = Vec::new();
    for w in &loaded.dict_words {
        let created = uow.create_orphan_dict_word(&DictWord {
            created_at: w.created_at,
            updated_at: w.updated_at,
            word: w.word.clone(),
            ..Default::default()
        })?;
        dict_word_ids.push(created.id);
    }

    // Binders -> items -> contents.
    let mut binder_map: HashMap<u64, EntityId> = HashMap::new();
    let mut item_map: HashMap<u64, EntityId> = HashMap::new();
    let mut binder_ids: Vec<EntityId> = Vec::new();
    let mut item_tag_links: Vec<(EntityId, Vec<u64>)> = Vec::new();

    for lb in &loaded.binders {
        let created_binder = uow.create_orphan_binder(&Binder {
            // Carried explicitly: `..Default::default()` below would otherwise
            // drop the uid the format just supplied, so every row would land in
            // the store with an empty identity. Minting when empty is the final
            // backstop for any load path that failed to provide one.
            uid: common::uid::heal_uid(lb.binder.uid),
            created_at: lb.binder.created_at,
            updated_at: lb.binder.updated_at,
            name: lb.binder.name.clone(),
            activated: lb.binder.activated,
            ..Default::default()
        })?;
        binder_map.insert(lb.binder.id, created_binder.id);

        let mut item_ids: Vec<EntityId> = Vec::new();
        for li in &lb.items {
            let mut content_ids: Vec<EntityId> = Vec::new();
            for c in &li.contents {
                let created_content = uow.create_orphan_content(&Content {
                    created_at: c.created_at,
                    updated_at: c.updated_at,
                    activated: c.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                    ..Default::default()
                })?;
                content_ids.push(created_content.id);
            }

            let i = &li.item;
            let created_item = uow.create_orphan_binder_item(&BinderItem {
                // See the binder above: carried explicitly, healed if empty.
                uid: common::uid::heal_uid(i.uid),
                created_at: i.created_at,
                updated_at: i.updated_at,
                title: i.title.clone(),
                sub_title: i.sub_title.clone(),
                role: i.role.clone(),
                sub_role: i.sub_role.clone(),
                label: i.label.clone(),
                activated: i.activated,
                is_favorite: i.is_favorite,
                is_exportable: i.is_exportable,
                indent: i.indent,
                word_count_goal: i.word_count_goal,
                char_count_goal: i.char_count_goal,
                dict_language: i.dict_language.clone(),
                // Must be explicit: `..Default::default()` below would silently swallow
                // it, and the aliases would be dropped on every load with nothing to
                // show for it. (`save_load_round_trip_through_store` covers this.)
                aliases: i.aliases.clone(),
                ..Default::default()
            })?;

            if !content_ids.is_empty() {
                uow.set_binder_item_relationship(
                    &created_item.id,
                    &BinderItemRelationshipField::Contents,
                    &content_ids,
                )?;
            }
            item_map.insert(li.item.id, created_item.id);
            if !li.tag_ids.is_empty() {
                item_tag_links.push((created_item.id, li.tag_ids.clone()));
            }
            item_ids.push(created_item.id);
        }

        uow.set_binder_relationship(
            &created_binder.id,
            &BinderRelationshipField::BinderItems,
            &item_ids,
        )?;
        binder_ids.push(created_binder.id);
    }

    // M2M item tags (remap file tag ids -> store ids).
    for (item_id, file_tag_ids) in &item_tag_links {
        let resolved: Vec<EntityId> = file_tag_ids
            .iter()
            .filter_map(|t| tag_map.get(t).copied())
            .collect();
        if !resolved.is_empty() {
            uow.set_binder_item_relationship(
                item_id,
                &BinderItemRelationshipField::Tags,
                &resolved,
            )?;
        }
    }

    // M2M self-references (cross-links), grouped by source.
    let mut refs_by_source: HashMap<EntityId, Vec<EntityId>> = HashMap::new();
    for (src, dst) in &loaded.references {
        if let (Some(&s), Some(&d)) = (item_map.get(src), item_map.get(dst)) {
            refs_by_source.entry(s).or_default().push(d);
        }
    }
    for (s, dsts) in &refs_by_source {
        uow.set_binder_item_relationship(s, &BinderItemRelationshipField::References, dsts)?;
    }

    // Trash index (remap origin + trashed targets).
    let mut trash_info_ids: Vec<EntityId> = Vec::new();
    for t in &loaded.trash_infos {
        let origin = if t.origin_binder_id == 0 {
            0
        } else {
            binder_map
                .get(&(t.origin_binder_id as u64))
                .copied()
                .map(|v| v as i64)
                .unwrap_or(0)
        };
        let info = uow.create_orphan_trash_info(&TrashInfo {
            created_at: t.created_at,
            updated_at: t.updated_at,
            trashed_at: t.trashed_at,
            origin_binder_id: origin,
            ..Default::default()
        })?;
        if let Some(b) = t.trashed_binder.and_then(|b| binder_map.get(&b).copied()) {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinder,
                &[b],
            )?;
        }
        if let Some(it) = t
            .trashed_binder_item
            .and_then(|i| item_map.get(&i).copied())
        {
            uow.set_trash_info_relationship(
                &info.id,
                &TrashInfoRelationshipField::TrashedBinderItem,
                &[it],
            )?;
        }
        trash_info_ids.push(info.id);
    }

    // Paces (Work trunk). Children are created first, then the Pace, then wired; the
    // weak `book_item`/`target_item` back-links are remapped through `item_map` (an
    // unresolvable id is simply dropped, same posture as trash back-links).
    let mut pace_ids: Vec<EntityId> = Vec::new();
    for lp in &loaded.paces {
        let mut holiday_ids: Vec<EntityId> = Vec::new();
        for h in &lp.holidays {
            let created = uow.create_orphan_holiday(&Holiday {
                created_at: h.created_at,
                updated_at: h.updated_at,
                label: h.label.clone(),
                start_date: h.start_date,
                end_date: h.end_date,
                ..Default::default()
            })?;
            holiday_ids.push(created.id);
        }
        let mut milestone_ids: Vec<EntityId> = Vec::new();
        for ms in &lp.milestones {
            let created = uow.create_orphan_milestone(&Milestone {
                created_at: ms.created_at,
                updated_at: ms.updated_at,
                label: ms.label.clone(),
                target_date: ms.target_date,
                target_word_count: ms.target_word_count,
                ..Default::default()
            })?;
            if let Some(it) = ms.target_item.and_then(|i| item_map.get(&i).copied()) {
                uow.set_milestone_relationship(
                    &created.id,
                    &MilestoneRelationshipField::TargetItem,
                    &[it],
                )?;
            }
            milestone_ids.push(created.id);
        }
        let pace = uow.create_orphan_pace(&Pace {
            created_at: lp.created_at,
            updated_at: lp.updated_at,
            start_date: lp.start_date,
            end_date: lp.end_date,
            weekday_mask: lp.weekday_mask,
            active: lp.active,
            ..Default::default()
        })?;
        if let Some(bi) = lp.book_item.and_then(|i| item_map.get(&i).copied()) {
            uow.set_pace_relationship(&pace.id, &PaceRelationshipField::BookItem, &[bi])?;
        }
        if !holiday_ids.is_empty() {
            uow.set_pace_relationship(&pace.id, &PaceRelationshipField::Holidays, &holiday_ids)?;
        }
        if !milestone_ids.is_empty() {
            uow.set_pace_relationship(
                &pace.id,
                &PaceRelationshipField::Milestones,
                &milestone_ids,
            )?;
        }
        pace_ids.push(pace.id);
    }

    // Work's owned collections.
    uow.set_work_relationship(&work.id, &WorkRelationshipField::Binders, &binder_ids)?;
    if !tag_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Tags, &tag_ids)?;
    }
    if !dict_word_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::DictWords, &dict_word_ids)?;
    }
    // Trash lives under the Work trunk (post-reparent).
    if !trash_info_ids.is_empty() {
        uow.set_work_relationship(
            &work.id,
            &WorkRelationshipField::TrashInfos,
            &trash_info_ids,
        )?;
    }
    if !pace_ids.is_empty() {
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Paces, &pace_ids)?;
    }

    // ProgressSnapshots — created here (needs `item_map` to remap the per-Book breakdown
    // ids), wired onto the fresh WorkInfo back in `create_trunk`. Both parallel arrays are
    // filtered in lockstep so an unresolvable book id drops its paired count too.
    let mut progress_snapshot_ids: Vec<EntityId> = Vec::new();
    for s in &loaded.progress_snapshots {
        let (book_ids, book_counts): (Vec<u64>, Vec<i64>) = s
            .book_item_ids
            .iter()
            .zip(&s.book_word_counts)
            .filter_map(|(fid, wc)| item_map.get(fid).copied().map(|id| (id, *wc)))
            .unzip();
        let created = uow.create_orphan_progress_snapshot(&ProgressSnapshot {
            created_at: s.created_at,
            updated_at: s.updated_at,
            day: s.day,
            total_word_count: s.total_word_count,
            total_char_count: s.total_char_count,
            book_item_ids: book_ids,
            book_word_counts: book_counts,
            ..Default::default()
        })?;
        progress_snapshot_ids.push(created.id);
    }

    Ok(Materialized {
        work_id: work.id,
        progress_snapshot_ids,
    })
}

/// Build the non-undoable trunk: System + RecentWork + WorkInfo (records the
/// opened path and its shape) + Root.
fn create_trunk(
    uow: &dyn LoadWorkUnitOfWorkTrait,
    loaded: &LoadedWork,
    mat: &Materialized,
    file_name: &str,
    shape: SkribShape,
    now: DateTime<Utc>,
) -> Result<()> {
    // Reuse the single shared System (seeded by `initialize_app`, or created by a
    // prior load/new); create one only if absent (e.g. a load before any init).
    let system_id = match uow.get_all_system()?.into_iter().next() {
        Some(system) => system.id,
        None => {
            uow.create_orphan_system(&System {
                created_at: now,
                updated_at: now,
                ..Default::default()
            })?
            .id
        }
    };

    let recent = uow.create_orphan_recent_work(&RecentWork {
        created_at: now,
        updated_at: now,
        title: loaded.work.title.clone(),
        last_opened_at: now,
        absolute_path: loaded.absolute_path.clone(),
        ..Default::default()
    })?;
    // Append to the existing recents rather than replacing them — the list
    // accumulates across opens (`close_work` leaves `RecentWork` rows in place).
    let mut recent_ids =
        uow.get_system_relationship(&system_id, &SystemRelationshipField::RecentWorks)?;
    recent_ids.push(recent.id);
    uow.set_system_relationship(
        &system_id,
        &SystemRelationshipField::RecentWorks,
        &recent_ids,
    )?;

    let work_shape = match shape {
        SkribShape::ExplodedFolder => WorkShape::Folder,
        SkribShape::ZipFile | SkribShape::LegacySqlite => WorkShape::Zip,
    };
    // Every Work gets its live Search surface, created eagerly alongside its
    // WorkInfo. `run_search` resolves it through `WorkInfo.search`, so a project
    // opened without one could never search. `Search`/`SearchResult` are
    // `undoable: false` and never round-trip through .skrib — this is a business
    // surface rebuilt per session, not persisted state. (The *parameters* that must
    // survive a restart live in the UI's `search.toml`, not here.)
    let search = uow.create_orphan_search(&Search {
        created_at: now,
        updated_at: now,
        ..Default::default()
    })?;
    let work_info = uow.create_orphan_work_info(&WorkInfo {
        created_at: now,
        updated_at: now,
        file_name: Some(file_name.to_string()),
        shape: work_shape,
        ..Default::default()
    })?;
    // Per-open-Work session info: link under System.work_infos and point it at
    // its Work (the multi-Work discriminator).
    uow.set_system_relationship(
        &system_id,
        &SystemRelationshipField::WorkInfos,
        &[work_info.id],
    )?;
    uow.set_work_info_relationship(
        &work_info.id,
        &WorkInfoRelationshipField::Search,
        &[search.id],
    )?;
    uow.set_work_info_relationship(
        &work_info.id,
        &WorkInfoRelationshipField::Work,
        &[mat.work_id],
    )?;
    // Hydrate the daily history onto the fresh WorkInfo (the reach-through-WorkInfo the
    // save path mirrors). The snapshot orphans were built in `materialize`.
    if !mat.progress_snapshot_ids.is_empty() {
        uow.set_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::ProgressSnapshots,
            &mat.progress_snapshot_ids,
        )?;
    }

    // Reuse the single shared Root (one per process; multiple Works hang off it).
    let root_id = match uow.get_all_root()?.into_iter().next() {
        Some(root) => root.id,
        None => {
            uow.create_orphan_root(&Root {
                created_at: now,
                updated_at: now,
                ..Default::default()
            })?
            .id
        }
    };
    uow.set_root_relationship(&root_id, &RootRelationshipField::System, &[system_id])?;
    // Single-project-at-a-time today: this Work replaces the previous one (already
    // cleared by `close_current_work`). Multiple-open (roadmap) will append here.
    uow.set_root_relationship(&root_id, &RootRelationshipField::Works, &[mat.work_id])?;
    Ok(())
}

/// Adapt the legacy SQLite reader's output to the neutral graph, assigning
/// internally-consistent file ids and reproducing the historic defaults
/// (`is_exportable = true`, trashed items stay in place indexed by TrashInfo).
fn legacy_to_loaded(p: legacy::LegacyProject, now: DateTime<Utc>) -> LoadedWork {
    use skrib::{LoadedBinder, LoadedItem, LoadedTrash};

    let mut next_id: u64 = 1;
    let mut fresh = || {
        let v = next_id;
        next_id += 1;
        v
    };

    let work = Work {
        id: fresh(),
        created_at: now,
        updated_at: now,
        title: p.title.clone(),
        author_name: p.author.clone(),
        // The legacy DB stores one space-separated string — split it here, exactly as the
        // pre-v4 bundle deserializer does, so both legacy paths agree.
        dict_language: p.dict_language.split_whitespace().map(String::from).collect(),
        // Carry the legacy id through; empty → minted at `materialize`.
        unique_id: p.unique_id.clone(),
        ..Default::default()
    };

    let mut tag_map: HashMap<i64, u64> = HashMap::new();
    let tags: Vec<BinderTag> = p
        .tags
        .iter()
        .map(|(old, t)| {
            let fid = fresh();
            tag_map.insert(*old, fid);
            BinderTag {
                id: fid,
                created_at: now,
                updated_at: now,
                name: t.name.clone(),
                color: t.color.clone(),
                // The legacy schema has no equivalent of either: a pre-3.0 project
                // never had tag descriptions, and nothing in it was story-bible
                // material for the mention index. Its `t_text_color` is deliberately
                // dropped — text colour is derived from `color` at render time now.
                details: String::new(),
                discoverable: false,
            }
        })
        .collect();

    let dict_words: Vec<DictWord> = p
        .dict_words
        .iter()
        .map(|w| DictWord {
            id: fresh(),
            created_at: now,
            updated_at: now,
            word: w.clone(),
        })
        .collect();

    let mut item_map: HashMap<i64, u64> = HashMap::new();
    let mut trash_infos: Vec<LoadedTrash> = Vec::new();
    let mut binders: Vec<LoadedBinder> = Vec::new();

    for b in &p.binders {
        let bfid = fresh();
        if !b.activated {
            trash_infos.push(LoadedTrash {
                created_at: now,
                updated_at: now,
                trashed_at: now,
                origin_binder_id: 0,
                trashed_binder: Some(bfid),
                trashed_binder_item: None,
            });
        }

        let mut items: Vec<LoadedItem> = Vec::new();
        for it in &b.items {
            let ifid = fresh();
            item_map.insert(it.old_id, ifid);

            let contents: Vec<Content> = it
                .contents
                .iter()
                .map(|c| Content {
                    id: fresh(),
                    created_at: now,
                    updated_at: now,
                    activated: it.activated,
                    role: c.role.clone(),
                    data: c.data.clone(),
                })
                .collect();

            if !it.activated {
                trash_infos.push(LoadedTrash {
                    created_at: now,
                    updated_at: now,
                    trashed_at: now,
                    origin_binder_id: bfid as i64,
                    trashed_binder: None,
                    trashed_binder_item: Some(ifid),
                });
            }

            let tag_ids: Vec<u64> = it
                .tag_old_ids
                .iter()
                .filter_map(|t| tag_map.get(t).copied())
                .collect();

            items.push(LoadedItem {
                item: BinderItem {
                    id: ifid,
                    // The legacy path builds its graph directly and never
                    // constructs a `WorkBundle`, so `migrate_bundle`'s minting
                    // step never sees these rows — mint here instead.
                    uid: common::uid::new_uid(),
                    created_at: now,
                    updated_at: now,
                    title: it.title.clone(),
                    sub_title: it.sub_title.clone(),
                    role: it.role.clone(),
                    sub_role: it.sub_role.clone(),
                    label: it.label.clone(),
                    activated: it.activated,
                    is_exportable: true,
                    indent: it.indent,
                    word_count_goal: it.word_count_goal,
                    char_count_goal: it.char_count_goal,
                    ..Default::default()
                },
                contents,
                tag_ids,
            });
        }

        binders.push(LoadedBinder {
            binder: Binder {
                id: bfid,
                // See the item above — the legacy path mints its own.
                uid: common::uid::new_uid(),
                created_at: now,
                updated_at: now,
                name: b.name.clone(),
                activated: b.activated,
                ..Default::default()
            },
            items,
        });
    }

    let references: Vec<(u64, u64)> = p
        .references
        .iter()
        .filter_map(
            |(src, dst)| match (item_map.get(src).copied(), item_map.get(dst).copied()) {
                (Some(s), Some(d)) => Some((s, d)),
                _ => None,
            },
        )
        .collect();

    LoadedWork {
        work,
        tags,
        dict_words,
        binders,
        trash_infos,
        // Legacy projects never had a writing plan.
        paces: Vec::new(),
        progress_snapshots: Vec::new(),
        references,
        absolute_path: p.absolute_path.clone(),
    }
}

#[cfg(test)]
mod legacy_uid_tests {
    use super::*;

    /// The legacy SQLite path builds its graph directly and never constructs a
    /// `WorkBundle`, so `migrate_bundle`'s minting step never sees these rows.
    /// A fix confined to `migration.rs` would silently miss every legacy
    /// project -- this pins the independent mint.
    #[test]
    fn a_legacy_project_gets_a_distinct_uid_for_every_row() {
        use legacy::{LegacyBinder, LegacyItem, LegacyProject};

        let item = |old_id: i64, title: &str| LegacyItem {
            old_id,
            title: title.to_string(),
            sub_title: String::new(),
            role: common::entities::BinderItemRole::Item,
            sub_role: common::entities::BinderItemSubRole::Scene,
            label: String::new(),
            activated: true,
            indent: 0,
            word_count_goal: 0,
            char_count_goal: 0,
            contents: Vec::new(),
            tag_old_ids: Vec::new(),
        };
        let project = LegacyProject {
            title: "Old Novel".into(),
            author: "A".into(),
            dict_language: "en-US".into(),
            unique_id: String::new(),
            absolute_path: "/tmp/old.skrib".into(),
            tags: Vec::new(),
            dict_words: Vec::new(),
            binders: vec![LegacyBinder {
                name: "Manuscript".into(),
                is_note: false,
                activated: true,
                items: vec![item(1, "One"), item(2, "Two"), item(3, "Three")],
            }],
            references: Vec::new(),
        };

        let loaded = legacy_to_loaded(project, chrono::Utc::now());

        let mut seen = std::collections::HashSet::new();
        for b in &loaded.binders {
            assert!(!b.binder.uid.is_nil(), "legacy binder left unidentified");
            assert!(seen.insert(b.binder.uid), "duplicate uid across legacy rows");
            for i in &b.items {
                assert!(!i.item.uid.is_nil(), "legacy item left unidentified");
                assert!(seen.insert(i.item.uid), "duplicate uid across legacy rows");
            }
        }
        assert_eq!(seen.len(), 4, "one binder + three items, all distinct");
    }
}
